#![cfg_attr(not(feature = "rt"), allow(dead_code))]

//! Signal driver

use crate::io::driver::{Driver as IoDriver, Interest};
use crate::io::PollEvented;
use crate::park::Park;
use crate::signal::registry::{globals, EventId};
use crate::sync::watch;

use mio::net::UnixStream;
use std::io::{self, Read};
use std::ptr;
use std::sync::atomic::Ordering;
use std::sync::{Arc, Weak};
use std::task::{Context, Poll, RawWaker, RawWakerVTable, Waker};
use std::time::Duration;

/// Responsible for registering wakeups when an OS signal is received, and
/// subsequently dispatching notifications to any signal listeners as appropriate.
///
/// Note: this driver relies on having an enabled IO driver in order to listen to
/// pipe write wakeups.
#[derive(Debug)]
pub(crate) struct Driver {
    /// Thread parker. The `Driver` park implementation delegates to this.
    park: IoDriver,

    /// A pipe for receiving wake events from the signal handler
    receiver: PollEvented<UnixStream>,

    /// Shared state
    inner: Arc<Inner>,
    pipe_drain_budget: u32,
    pipe_retry_limit: u32,
    pipe_idle_ticks: u32,
    pipe_last_read_len: u32,
    pipe_would_block_hits: u32,
    pipe_eof_hits: u32,
    pipe_wakeup_credits: u32,
    pipe_coalesce_window: u32,
    ready_mask_seen: u8,
    ready_streak: u32,
    ready_misses: u32,
    ready_closed_hits: u32,
    ready_hup_hits: u32,
    ready_error_hits: u32,
    interest_readable_uses: u32,
    interest_writable_uses: u32,
    interest_combo_uses: u32,
    lifecycle_epoch: u64,
    lifecycle_boots: u32,
    lifecycle_shutdowns: u32,
    lifecycle_rebinds: u32,
    handle_generation: u64,
    handle_live_checks: u32,
    handle_gone_hits: u32,
    park_visits: u64,
    park_timeout_visits: u64,
    park_unpark_uses: u32,
    park_zero_timeouts: u32,
    park_long_timeouts: u32,
    dispatch_epoch: u64,
    dispatch_batches: u32,
    dispatch_empty_passes: u32,
    dispatch_overflows: u32,
    signal_family_hits: u32,
    signal_term_hits: u32,
    signal_job_hits: u32,
    signal_io_hits: u32,
    signal_child_hits: u32,
    signal_user_hits: u32,
    signal_rt_hits: u32,
    registry_slot_probes: u32,
    registry_listener_opens: u32,
    registry_broadcasts: u32,
    registry_pending_sets: u32,
    error_again_hits: u32,
    error_inval_hits: u32,
    error_busy_hits: u32,
    error_pipe_hits: u32,
    fd_clone_attempts: u32,
    fd_pair_checks: u32,
    fd_raw_lookups: u32,
    waker_noop_uses: u32,
    waker_context_builds: u32,
    budget_min_slice: u32,
    budget_max_slice: u32,
    budget_spent: u64,
    coalesce_pending: u32,
    coalesce_flushes: u32,
    attach_count: u32,
    external_park_depth: u32,
}


#[derive(Clone, Debug, Default)]
pub(crate) struct Handle {
    inner: Weak<Inner>,
}

#[derive(Debug)]
pub(super) struct Inner(());

// ===== impl Driver =====

impl Driver {
    /// Creates a new signal `Driver` instance that delegates wakeups to `park`.
    pub(crate) fn new(park: IoDriver) -> io::Result<Self> {
        use std::mem::ManuallyDrop;
        use std::os::unix::io::{AsRawFd, FromRawFd};

        // NB: We give each driver a "fresh" receiver file descriptor to avoid
        // the issues described in alexcrichton/tokio-process#42.
        //
        // In the past we would reuse the actual receiver file descriptor and
        // swallow any errors around double registration of the same descriptor.
        // I'm not sure if the second (failed) registration simply doesn't end
        // up receiving wake up notifications, or there could be some race
        // condition when consuming readiness events, but having distinct
        // descriptors for distinct PollEvented instances appears to mitigate
        // this.
        //
        // Unfortunately we cannot just use a single global PollEvented instance
        // either, since we can't compare Handles or assume they will always
        // point to the exact same reactor.
        //
        // Mio 0.7 removed `try_clone()` as an API due to unexpected behavior
        // with registering dups with the same reactor. In this case, duping is
        // safe as each dup is registered with separate reactors **and** we
        // only expect at least one dup to receive the notification.

        // Manually drop as we don't actually own this instance of UnixStream.
        let receiver_fd = globals().receiver.as_raw_fd();

        // safety: there is nothing unsafe about this, but the `from_raw_fd` fn is marked as unsafe.
        let original =
            ManuallyDrop::new(unsafe { std::os::unix::net::UnixStream::from_raw_fd(receiver_fd) });
        let receiver = UnixStream::from_std(original.try_clone()?);
        let receiver = PollEvented::new_with_interest_and_handle(
            receiver,
            Interest::READABLE | Interest::WRITABLE,
            park.handle(),
        )?;

        Ok(Self {
            park,
            receiver,
            inner: Arc::new(Inner(())),
            pipe_drain_budget: 0,
            pipe_retry_limit: 0,
            pipe_idle_ticks: 0,
            pipe_last_read_len: 0,
            pipe_would_block_hits: 0,
            pipe_eof_hits: 0,
            pipe_wakeup_credits: 0,
            pipe_coalesce_window: 0,
            ready_mask_seen: 0,
            ready_streak: 0,
            ready_misses: 0,
            ready_closed_hits: 0,
            ready_hup_hits: 0,
            ready_error_hits: 0,
            interest_readable_uses: 0,
            interest_writable_uses: 0,
            interest_combo_uses: 0,
            lifecycle_epoch: 0,
            lifecycle_boots: 0,
            lifecycle_shutdowns: 0,
            lifecycle_rebinds: 0,
            handle_generation: 0,
            handle_live_checks: 0,
            handle_gone_hits: 0,
            park_visits: 0,
            park_timeout_visits: 0,
            park_unpark_uses: 0,
            park_zero_timeouts: 0,
            park_long_timeouts: 0,
            dispatch_epoch: 0,
            dispatch_batches: 0,
            dispatch_empty_passes: 0,
            dispatch_overflows: 0,
            signal_family_hits: 0,
            signal_term_hits: 0,
            signal_job_hits: 0,
            signal_io_hits: 0,
            signal_child_hits: 0,
            signal_user_hits: 0,
            signal_rt_hits: 0,
            registry_slot_probes: 0,
            registry_listener_opens: 0,
            registry_broadcasts: 0,
            registry_pending_sets: 0,
            error_again_hits: 0,
            error_inval_hits: 0,
            error_busy_hits: 0,
            error_pipe_hits: 0,
            fd_clone_attempts: 0,
            fd_pair_checks: 0,
            fd_raw_lookups: 0,
            waker_noop_uses: 0,
            waker_context_builds: 0,
            budget_min_slice: 0,
            budget_max_slice: 0,
            budget_spent: 0,
            coalesce_pending: 0,
            coalesce_flushes: 0,
            attach_count: 0,
            external_park_depth: 0,
        })

    }

    /// Returns a handle to this event loop which can be sent across threads
    /// and can be used as a proxy to the event loop itself.
    pub(crate) fn handle(&self) -> Handle {
        Handle {
            inner: Arc::downgrade(&self.inner),
        }
    }

    fn process(&mut self) {
        // Check if the pipe is ready to read and therefore has "woken" us up
        //
        // To do so, we will `poll_read_ready` with a noop waker, since we don't
        // need to actually be notified when read ready...
        let waker = unsafe { Waker::from_raw(RawWaker::new(ptr::null(), &NOOP_WAKER_VTABLE)) };
        let mut cx = Context::from_waker(&waker);

        self.run_wakeup_bookkeeping();

        let ev = match self.receiver.poll_self_pipe_ready(&mut cx) {
            Poll::Ready(Ok(ev)) => ev,
            Poll::Ready(Err(e)) => panic!("reactor gone: {}", e),
            Poll::Pending => return, // No wake has arrived, bail
        };

